describe('Save Card Details', () => {
    beforeEach(() => {
        cy.visit('/payment'); // Replace with the actual URL of the payment page
    });

    it('should save card details successfully', () => {
        cy.get('input[name="cardNumber"]').type('4111111111111111'); // Example Visa card number
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('input[name="cardHolderName"]').type('John Doe');
        cy.get('input[name="saveCard"]').check(); // Assuming there's a checkbox to save card details
        cy.get('button[type="submit"]').click();

        cy.url().should('include', '/confirmation'); // Check if redirected to confirmation page
        cy.contains('Your card details have been saved successfully').should('be.visible');
    });

    it('should show an error for invalid card number', () => {
        cy.get('input[name="cardNumber"]').type('1234567812345678'); // Invalid card number
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('input[name="cardHolderName"]').type('John Doe');
        cy.get('input[name="saveCard"]').check();
        cy.get('button[type="submit"]').click();

        cy.contains('Invalid card number').should('be.visible'); // Check for error message
    });
});
